import type { CourseChapter, ChapterContent, CourseQuestion } from './types';

const q = (id: string, question: string, correctId: string, choices: [string, string, string][]): CourseQuestion => {
  const options = choices.map(([id, text, feedback]) => ({ id, text, feedback }));
  // A fixed authored order, identical across locales and visits; no correct-position shortcut.
  const position = id === 'attention-mask' ? 1 : id === 'safety-release' ? 2
    : [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0) % options.length;
  const correct = options.find(option => option.id === correctId)!;
  const ordered = options.filter(option => option.id !== correctId);
  ordered.splice(position, 0, correct);
  return { id, question, correctId, options: ordered };
};
const make = (id: CourseChapter['experimentKind'], order: number, prerequisite: string, minutes: number, zh: ChapterContent, en: ChapterContent): CourseChapter => ({ id, order, prerequisites: [prerequisite], minutes, experimentKind: id, content: { 'zh-CN': zh, en } });

